    path = f'{MODEL_DIR}/{file_name}'
    if os.path.exists(path):
        return joblib.load(path), 'nạp từ file .joblib (mục 3.5.5)'
    return builder().fit(X_train, y_train), 'huấn luyện lại trên Train'

