import os
import joblib

from sklearn.pipeline import Pipeline
from sklearn.dummy import DummyRegressor
from sklearn.metrics import (
    mean_absolute_error,
    mean_squared_error,
    r2_score
)

def load_existing_model(
    var_names,
    filenames,
    description
):
    # Ưu tiên mô hình đã tồn tại trong phiên Colab
    for name in var_names:
        if name in globals():
            model = globals()[name]

            if hasattr(model, "predict"):
                return model, f"Biến {name}"

    # Nếu không có, nạp Pipeline đã lưu
    for filename in filenames:
        path = os.path.join(MODEL_DIR, filename)

        if os.path.isfile(path):
            model = joblib.load(path)

            if not hasattr(model, "predict"):
                raise TypeError(
                    f"File {path} không chứa mô hình dự đoán."
                )

            return model, f"File {filename}"

    raise RuntimeError(
        f"Không tìm thấy {description}. "
        "Hãy chạy/nạp mô hình từ mục 3.5 hoặc 4.3 "
        "trước khi thực hiện 4.4."
    )


# 1. DummyRegressor - Baseline mục 4.1.2
baseline_model = DummyRegressor(
    strategy="mean"
).fit(X_train, y_train)

# 2. Linear Regression - mục 3.5.2
lr_model, lr_source = load_existing_model(
    var_names=["lr_model"],
    filenames=["linear_regression_pipeline.joblib"],
    description="Linear Regression"
)

# 3. Decision Tree sau tối ưu - mục 4.3.3
dt_tuned, dt_source = load_existing_model(
    var_names=["best_dt", "dt_tuned"],
    filenames=[
        "decision_tree_tuned_pipeline.joblib"
    ],
    description="Decision Tree sau tối ưu"
)

# 4. Random Forest sau tối ưu - mục 4.3.4
rf_tuned, rf_source = load_existing_model(
    var_names=["best_rf", "rf_tuned"],
    filenames=[
        "random_forest_tuned_pipeline.joblib"
    ],
    description="Random Forest sau tối ưu"
)

# 5. Decision Tree trước tối ưu - mục 3.5.3
dt_init, dt_init_source = load_existing_model(
    var_names=["dt_init"],
    filenames=[
        "decision_tree_pipeline.joblib"
    ],
    description="Decision Tree ban đầu"
)

# 6. Random Forest trước tối ưu - mục 3.5.4
rf_init, rf_init_source = load_existing_model(
    var_names=["rf_init"],
    filenames=[
        "random_forest_pipeline.joblib"
    ],
    description="Random Forest ban đầu"
)


# Các mô hình sử dụng trong 4.4.1 - 4.4.5
MODELS = {
    "Baseline": baseline_model,
    "Linear Regression": lr_model,
    "Decision Tree": dt_tuned,
    "Random Forest": rf_tuned
}

COLORS = {
    "Baseline": "#8C8C8C",
    "Linear Regression": "#4C72B0",
    "Decision Tree": "#55A868",
    "Random Forest": "#DD8452"
}

source = {
    "Baseline": "DummyRegressor từ Train",
    "Linear Regression": lr_source,
    "Decision Tree": dt_source,
    "Random Forest": rf_source,
    "Decision Tree trước tối ưu": dt_init_source,
    "Random Forest trước tối ưu": rf_init_source
}

# Không đưa Test vào SETS
SETS = {
    "train": (X_train, y_train),
    "val": (X_val, y_val)
}

Y = {
    s: np.asarray(y)
    for s, (_, y) in SETS.items()
}

PRED = {
    s: {
        name: model.predict(X)
        for name, model in MODELS.items()
    }
    for s, (X, _) in SETS.items()
}


def metrics(y_true, y_pred):
    mse = mean_squared_error(y_true, y_pred)

    return {
        "MAE": mean_absolute_error(y_true, y_pred),
        "MSE": mse,
        "RMSE": float(np.sqrt(mse)),
        "R²": r2_score(y_true, y_pred)
    }


print("=== NGUỒN MÔ HÌNH ===")
display(
    pd.Series(source, name="Nguồn").to_frame()
)

print("\n=== VALIDATION METRICS ===")

validation_check = pd.DataFrame({
    name: metrics(Y["val"], PRED["val"][name])
    for name in MODELS
}).T

display(validation_check.round(6))

# Kiểm tra các giá trị đã báo cáo ở 4.1-4.3.
# Nếu lệch, cần xác minh mô hình và dữ liệu,
# không tự sửa số liệu cho khớp.
expected_rmse = {
    "Baseline": 1.73783635,
    "Linear Regression": 1.737879,
    "Decision Tree": 1.737896,
    "Random Forest": 1.737905
}

print("\n=== KIỂM TRA TÍNH NHẤT QUÁN ===")

for name, expected in expected_rmse.items():
    actual = validation_check.loc[name, "RMSE"]
    delta = actual - expected

    print(
        f"{name}: RMSE={actual:.8f}, "
        f"chênh lệch={delta:+.8f}"
    )

    if not np.isclose(actual, expected, atol=1e-5, rtol=0):
        print(
            "  [CẢNH BÁO] Kết quả không khớp "
            "mục 4.1-4.3. Cần kiểm tra lại."
        )

print("\n[OK] Không sử dụng Test trong mục 4.4.")

